from pathlib import Path
import json,re,hashlib
R=Path(__file__).resolve().parents[1];sha=lambda s:hashlib.sha256(s.encode('utf8')).hexdigest()
henan={32:'相邻项依次乘3、4、7。乘数满足前两项相加等于后一项，所以下一乘数为4+7=11，所求为168×11=1848，选B。',33:'从第三项起，每项等于前两项之和：7+14=21，14+21=35，21+35=56，下一项为35+56=91，选D。',34:'按相邻两项分组：245+168=413，249+164=413，254+159=413，因此260与未知项的和也为413，未知项为153，选A。',37:'从第四项起，每项等于前三项之和：1+3+4=8，3+4+8=15，下一项为4+8+15=27，选D。',38:'相邻项差依次为3、9、27、81，是公比3的等比数列。下一差为243，所求为131+243=374，选D。',39:'相邻项差为4、6、8，下一差为10，所以未知项为20+10=30，选D。',40:'各项分子均为1，分母依次为2、3、5、7、11、13，是连续质数。下一质数为17，未知项为1/17，对应A。'}
black={56:'设带2名徒弟的高级导师为x人，带3名徒弟的为x+2人。12名初级导师带12名徒弟，余下16名徒弟由高级导师带，故2x+3(x+2)=16，解得x=2。高级导师共2+4=6人，参与者共6+12+28=46人，选B。',57:'三个路口红灯概率依次为0.3、0.4、0.5。按题目的独立路口概率模型，最多遇到一个红灯的概率为：0.7×0.6×0.5 + 0.3×0.6×0.5 + 0.7×0.4×0.5 + 0.7×0.6×0.5 = 0.65，即65%，对应C。',58:'四人总分为82×4=328，甲乙丙总分为80×3=240，因此丁得88分。丙丁总分为85×2=170，丙得170−88=82分，选A。',59:'设准时x单、超时y单，则5x+2y=188，且x、y为非负整数。x不超过37；因188−5x须为偶数，x必须为偶数，故最大x=36，此时y=4，选C。',60:'第一次相遇需10÷(45+5)=0.2小时，信鸽飞9千米；休息0.3小时再飞回原地，往返飞18千米，累计耗时0.7小时。再休息0.3小时后，小吴已走5千米，剩余5千米。第二次相遇需5÷50=0.1小时，信鸽单程飞4.5千米，往返9千米。总飞行路程为18+9=27千米，选B。',61:'甲最先下车，三人合乘部分总费用为14×3=42元；乙、丙继续合乘的路段，乙分摊28−14=14元，故该段总费用为28元。乙独乘到自己下车点原需42+28=70元，实际付28元，节约42元，选C。',62:'将往返路线展开，二人的速度和为12千米/小时，路线往返长度为12千米，因此每隔1小时相遇一次；同向追及对应的每3小时相遇已包含在该序列中，不重复计次。第7次相遇发生在7小时，小王走28千米，即两个往返24千米再走4千米，距起点4千米，选D。',63:'把教材总数记为T。由“是其余教材的1/4、3/7、7/13”，可知语文、数学、英语分别占总数的1/5、3/10、7/20，科学占3/20。数学比科学多3T/20=30，故T=200，数学为60本，选B。',64:'设两队效率为a、b，总工作量为W，则6a+15b=W，24a+6b=W。相减得18a=9b，即b=2a。故W=6a+30a=36a，甲独做需36天，选C。',65:'设乘车总时长为t小时，通话、待机各t/2小时。总耗电比例为t/(2×6)+t/(2×210)=1，得t=35/3小时，即11小时40分钟，选D。',69:'顶点形状叠加规律为：两图同位置均为圆时结果为圆，其余组合均为方；连线规律为：相同线型叠加为实线，不同线型叠加为虚线。将此规则用于第二组六边形，只有C的顶点与线型同时吻合，选C。',101:'2015年从业人员为900−110=790万人，营业收入为4400亿元。人均收入为4400÷790≈5.57万元，最接近5.6万元，选C。',102:'2017年接待28亿人次，2012年为7.2亿人次。增加倍数为(28−7.2)÷7.2≈2.89，约增加3倍，选B。',103:'2014年增速为(12−10)÷10=20%；2015年为(22−12)÷12≈83.33%。两者之比为83.33%÷20%≈4.17，最接近4.2倍，选C。',104:'本题将“年均增长率”按累计增长率除以5年计算，即[(28−7.2)÷7.2]÷5≈57.78%；材料给出的复合增长率为31.2%，相差26.58个百分点，最接近26.6个百分点，选B。该口径与逐年同比增速的算术平均不同，应依本题与选项配合解读。',105:'2012至2017年的平均每年增加量为(28−7.2)÷5=4.16亿人次，超过4亿，故C正确。A缺少2017年经营单位总数，无法计算；B中2016年国内旅游收入约为5700÷(16.2%−1.7%)≈3.93万亿元；D中2013年收入增速16.67%大于2014年的14.29%。',106:'中国GDP为12.3万亿美元，占世界约15%，故世界经济总量约为12.3÷15%=82万亿美元，选B。',107:'逐年用出口减进口：2014年23526亿元，2015年36731亿元，2016年33452亿元，2017年28719亿元。最大值出现在2015年，选C。',108:'2017年总额4.1万亿美元即41000亿美元，1978年为206亿美元。增加倍数为41000÷206−1≈198.03，选B。',109:'增长量公式为“现期量×增长率÷(1+增长率)”。出口增加43045×12.1%÷112.1%≈4646亿元；进口增加30700×26.8%÷126.8%≈6489亿元，相差约1843亿元，最接近1842亿元，选B。',110:'A中年均增速差约6.6个百分点；B中2016年GDP为12.3−1.2=11.1万亿美元；C中差额为43045−30700=12345亿元，均成立。D中2017年进出口总额增加量为(153321+124602)−(138419+104967)=34537亿元，约3.45万亿元，未超过4万亿元，所以选D。',111:'研发支出为GDP乘研发占比：83608.59×2.56%≈2140.38亿元，选B。',112:'2014年先进制造业占比为49.39%−1.2%=48.19%，高技术制造业占比为27.6%−3.5%=24.1%。两者分母都是规模以上工业增加值，因此前者约为后者48.19÷24.1≈2.00倍，选B。',113:'表中每万人口发明专利拥有量指数由2014年的37.3%升至2018年的77.7%，四年平均增加(77.7−37.3)÷4=10.1个百分点，选D。',114:'直接比较表中“变动幅度”一列：高新技术企业数量为47.0个百分点，每万人口发明专利拥有量40.4个百分点，高技术制造业占比14.3个百分点，依次递减，对应A。',115:'A中创新驱动指数的相对增长率超过24%，成立。B不成立，因为2014、2015两年先进制造业占比指数同为92.1%；C把2018年排名误推到2014年；D使用了材料未提供的2019年数据，故选A。',116:'2013年粮食作物播种面积为721.1−159.4=561.7万公顷，2018年为679.0万公顷。增长率为(679.0−561.7)÷561.7≈20.88%，对应B。',117:'大豆增速为(179.4−108.4)÷108.4≈65.50%；玉米为(2700−2085)÷2085≈29.50%。前者约多36.00个百分点，选A。',118:'2015年增速约4.75%，2016年为负，2017年约4.59%，2018年约5.16%。最高为2018年，选D。',119:'2016年油料为201.5+24=225.5万吨；甜菜约为515.9÷1.498÷1.364≈252.5万吨；水果为225.5÷71.3%≈316.3万吨；小麦169.9万吨。水果最多，选C。原资料解析末句“316吨”单位有误，此处按材料校正为万吨。',120:'A中六年猪肉平均产量为(73.4+73.3+70.8+72.1+73.5+71.4)÷6≈72.42万吨；B中2017年粮食增速为9.2%−9.6%=−0.4%；C中机械化水平由79.8%升至84.0%，增加4.2个百分点；三项均不成立。D中稻谷年均复合增速为(121.9÷53.2)^(1/3)−1≈31.8%，约32%，选D。'}
changes=[]
for rel,mp in [('省考/河南/2019/行测-司法所.md',henan),('省考/黑龙江/2019/行测-边境县.md',black)]:
 p=R/rel;old=p.read_text(encoding='utf8');new=old
 for n,body in mp.items():
  pat=r'(<summary>第 '+str(n)+r' 题</summary>\s*\*\*答案\*\*[：:]\s*[ABCD]+)(.*?)(\*\*来源\*\*：.*?</details>)';m=re.search(pat,new,re.S);assert m,(rel,n)
  new=new[:m.start()]+m[1]+'\n\n**原创校核解析（AI辅助整理，非官方标准答案）**\n\n'+body+'\n\n**校核方法**：根据本卷题面与已收录公式/统计图独立演算，并与用户提供的同卷参考解析交叉核对；修补PDF文字提取遗漏的算式。\n\n'+m[3]+new[m.end():]
 changes.append(dict(path=rel,before_sha256=sha(old),after_sha256=sha(new),rewritten_questions=sorted(mp)))
 p.write_text(new,encoding='utf8',newline='\n')
(R/'reports/FULL-REPAIR-APTITUDE-MATH-20261015.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print(json.dumps({'math_explanations_rewritten':sum(len(x['rewritten_questions']) for x in changes)},ensure_ascii=False))
